-- Create "report_history" table
CREATE TABLE "report_history" ("id" character varying NOT NULL, "history_time" timestamptz NOT NULL, "ref" character varying NULL, "operation" character varying NOT NULL, "created_at" timestamptz NULL, "updated_at" timestamptz NULL, "created_by" character varying NULL, "updated_by" character varying NULL, "updated_by_impersonator" character varying NULL, "deleted_at" timestamptz NULL, "deleted_by" character varying NULL, "display_id" character varying NOT NULL, "tags" jsonb NULL, "requestor_id" character varying NULL, "owner_id" character varying NULL, "report_kind_name" character varying NULL, "report_kind_id" character varying NULL, "name" character varying NOT NULL, "query" text NOT NULL, "variables" jsonb NULL, "status" character varying NOT NULL DEFAULT 'DRAFT', "visibility" character varying NULL, "report_owner_id" character varying NULL, PRIMARY KEY ("id"));
-- Create index "reporthistory_history_time" to table: "report_history"
CREATE INDEX "reporthistory_history_time" ON "report_history" ("history_time");
-- Create "report_membership_history" table
CREATE TABLE "report_membership_history" ("id" character varying NOT NULL, "history_time" timestamptz NOT NULL, "ref" character varying NULL, "operation" character varying NOT NULL, "created_at" timestamptz NULL, "updated_at" timestamptz NULL, "created_by" character varying NULL, "updated_by" character varying NULL, "updated_by_impersonator" character varying NULL, "role" character varying NOT NULL DEFAULT 'MEMBER', "report_id" character varying NOT NULL, "user_id" character varying NOT NULL, PRIMARY KEY ("id"));
-- Create index "reportmembershiphistory_history_time" to table: "report_membership_history"
CREATE INDEX "reportmembershiphistory_history_time" ON "report_membership_history" ("history_time");
